const STAGES = ['待投递', '已投递', '面试中', '已结束'];
const ALL = '全部';
const STORAGE_KEY = 'jobApplications';

const shell = app;
const listEl = shell.querySelector('[data-role="record-list"]');
const emptyHintEl = shell.querySelector('[data-role="empty-hint"]');
const summaryEl = shell.querySelector('[data-role="list-summary"]');
const errorEl = shell.querySelector('[data-role="error"]');
const statEls = Array.from(shell.querySelectorAll('[data-stat]'));
const statCards = Array.from(shell.querySelectorAll('.stat-card'));
const chips = Array.from(shell.querySelectorAll('.chip'));

const formMask = shell.querySelector('[data-role="form-mask"]');
const formEl = shell.querySelector('[data-role="record-form"]');
const formTitleEl = shell.querySelector('[data-role="form-title"]');
const formErrorEl = shell.querySelector('[data-role="form-error"]');
const submitBtn = shell.querySelector('[data-role="submit-btn"]');
const fieldEls = {
  company: formEl.querySelector('[data-field="company"]'),
  position: formEl.querySelector('[data-field="position"]'),
  applyDate: formEl.querySelector('[data-field="applyDate"]'),
  stage: formEl.querySelector('[data-field="stage"]'),
  note: formEl.querySelector('[data-field="note"]')
};

const confirmMask = shell.querySelector('[data-role="confirm-mask"]');
const confirmTextEl = shell.querySelector('[data-role="confirm-text"]');

let records = [];
let filter = ALL;
let editingId = null;
let pendingDeleteId = null;
let lastFocused = null;

function normalizeStage(value) {
  return STAGES.indexOf(value) >= 0 ? value : STAGES[0];
}

function normalizeRecord(raw) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const id = typeof source.id === 'string' && source.id ? source.id : createId();
  return {
    ...source,
    id: id,
    company: typeof source.company === 'string' ? source.company : '',
    position: typeof source.position === 'string' ? source.position : '',
    applyDate: typeof source.applyDate === 'string' ? source.applyDate : '',
    stage: normalizeStage(source.stage),
    note: typeof source.note === 'string' ? source.note : ''
  };
}

function createId() {
  return 'rec-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
}

function todayISO() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return d.getFullYear() + '-' + m + '-' + day;
}

function showError(message) {
  if (message) {
    errorEl.textContent = message;
    errorEl.hidden = false;
  } else {
    errorEl.textContent = '';
    errorEl.hidden = true;
  }
}

function showFormError(message) {
  if (message) {
    formErrorEl.textContent = message;
    formErrorEl.hidden = false;
  } else {
    formErrorEl.textContent = '';
    formErrorEl.hidden = true;
  }
}

function countByStage() {
  const counts = { [ALL]: records.length };
  STAGES.forEach(function (stage) {
    counts[stage] = 0;
  });
  records.forEach(function (record) {
    const stage = normalizeStage(record.stage);
    counts[stage] += 1;
  });
  return counts;
}

function renderStats() {
  const counts = countByStage();
  statEls.forEach(function (el) {
    const key = el.getAttribute('data-stat');
    el.textContent = String(counts[key] || 0);
  });
  statCards.forEach(function (card) {
    const key = card.getAttribute('data-filter');
    card.classList.toggle('is-active', key === filter);
  });
}

function renderChips() {
  chips.forEach(function (chip) {
    const key = chip.getAttribute('data-filter');
    chip.classList.toggle('is-active', key === filter);
  });
}

function visibleRecords() {
  if (filter === ALL) {
    return records.slice();
  }
  return records.filter(function (record) {
    return normalizeStage(record.stage) === filter;
  });
}

function buildRecordCard(record) {
  const li = document.createElement('li');
  li.className = 'record-card';
  li.setAttribute('data-stage', normalizeStage(record.stage));
  li.setAttribute('data-id', record.id);

  const head = document.createElement('div');
  head.className = 'record-head';

  const titleBox = document.createElement('div');
  const companyEl = document.createElement('h3');
  companyEl.className = 'record-company';
  companyEl.textContent = record.company || '未填写公司';
  const positionEl = document.createElement('p');
  positionEl.className = 'record-position';
  positionEl.textContent = record.position || '未填写岗位';
  titleBox.appendChild(companyEl);
  titleBox.appendChild(positionEl);

  const tag = document.createElement('span');
  tag.className = 'stage-tag';
  tag.setAttribute('data-stage', normalizeStage(record.stage));
  tag.textContent = normalizeStage(record.stage);

  head.appendChild(titleBox);
  head.appendChild(tag);

  const meta = document.createElement('p');
  meta.className = 'record-meta';
  const dateSpan = document.createElement('span');
  dateSpan.textContent = '投递日期：' + (record.applyDate || '未填写');
  meta.appendChild(dateSpan);

  li.appendChild(head);
  li.appendChild(meta);

  if (record.note) {
    const noteEl = document.createElement('p');
    noteEl.className = 'record-note';
    noteEl.textContent = record.note;
    li.appendChild(noteEl);
  }

  const actions = document.createElement('div');
  actions.className = 'record-actions';

  const editBtn = document.createElement('button');
  editBtn.type = 'button';
  editBtn.className = 'btn btn-edit';
  editBtn.setAttribute('data-action', 'edit');
  editBtn.setAttribute('data-id', record.id);
  editBtn.textContent = '编辑';

  const deleteBtn = document.createElement('button');
  deleteBtn.type = 'button';
  deleteBtn.className = 'btn btn-delete';
  deleteBtn.setAttribute('data-action', 'delete');
  deleteBtn.setAttribute('data-id', record.id);
  deleteBtn.textContent = '删除';

  actions.appendChild(editBtn);
  actions.appendChild(deleteBtn);
  li.appendChild(actions);

  return li;
}

function renderList() {
  const items = visibleRecords();
  listEl.textContent = '';
  items.forEach(function (record) {
    listEl.appendChild(buildRecordCard(record));
  });

  const counts = countByStage();
  const filterLabel = filter === ALL ? '全部阶段' : filter;
  summaryEl.textContent = '当前筛选：' + filterLabel + '，共 ' + items.length + ' 条记录（总计 ' + counts[ALL] + ' 条）';

  emptyHintEl.hidden = items.length > 0;
  if (items.length === 0) {
    emptyHintEl.textContent = records.length === 0
      ? '还没有投递记录，点击右上角「新增投递」开始记录。'
      : '当前阶段下暂无记录，可切换筛选查看其他阶段。';
  }
}

function renderAll() {
  renderStats();
  renderChips();
  renderList();
}

async function persist(nextRecords) {
  const state = await appStore.getState();
  const next = Object.assign({}, state || {}, { [STORAGE_KEY]: nextRecords });
  await appStore.setState(next);
}

function openForm(record) {
  editingId = record ? record.id : null;
  formTitleEl.textContent = record ? '编辑投递记录' : '新增投递记录';
  submitBtn.textContent = record ? '保存修改' : '保存';
  fieldEls.company.value = record ? record.company : '';
  fieldEls.position.value = record ? record.position : '';
  fieldEls.applyDate.value = record ? record.applyDate : todayISO();
  fieldEls.stage.value = record ? normalizeStage(record.stage) : STAGES[0];
  fieldEls.note.value = record ? record.note : '';
  showFormError('');
  lastFocused = document.activeElement;
  formMask.hidden = false;
  fieldEls.company.focus();
}

function closeForm() {
  formMask.hidden = true;
  editingId = null;
  showFormError('');
  if (lastFocused && typeof lastFocused.focus === 'function') {
    lastFocused.focus();
  }
}

function openConfirm(id) {
  const record = records.find(function (item) { return item.id === id; });
  if (!record) {
    return;
  }
  pendingDeleteId = id;
  confirmTextEl.textContent = '确定要删除「' + (record.company || '未填写公司') + ' · ' + (record.position || '未填写岗位') + '」这条投递记录吗？删除后无法恢复。';
  lastFocused = document.activeElement;
  confirmMask.hidden = false;
  const confirmBtn = confirmMask.querySelector('[data-action="confirm-delete"]');
  if (confirmBtn) {
    confirmBtn.focus();
  }
}

function closeConfirm() {
  confirmMask.hidden = true;
  pendingDeleteId = null;
  if (lastFocused && typeof lastFocused.focus === 'function') {
    lastFocused.focus();
  }
}

async function handleSubmit(event) {
  event.preventDefault();
  const company = fieldEls.company.value.trim();
  const position = fieldEls.position.value.trim();
  const applyDate = fieldEls.applyDate.value;
  const stage = normalizeStage(fieldEls.stage.value);
  const note = fieldEls.note.value.trim();

  if (!company) {
    showFormError('请填写公司名称。');
    fieldEls.company.focus();
    return;
  }
  if (!position) {
    showFormError('请填写应聘岗位。');
    fieldEls.position.focus();
    return;
  }

  const payload = {
    company: company,
    position: position,
    applyDate: applyDate,
    stage: stage,
    note: note
  };

  let nextRecords;
  if (editingId) {
    nextRecords = records.map(function (record) {
      if (record.id !== editingId) {
        return record;
      }
      return Object.assign({}, record, payload);
    });
  } else {
    nextRecords = records.concat([Object.assign({ id: createId() }, payload)]);
  }

  submitBtn.disabled = true;
  try {
    await persist(nextRecords);
    records = nextRecords;
    showError('');
    closeForm();
    renderAll();
  } catch (err) {
    showFormError('保存失败，请重试。你的输入已保留。');
  } finally {
    submitBtn.disabled = false;
  }
}

async function handleDelete() {
  const id = pendingDeleteId;
  if (!id) {
    return;
  }
  const nextRecords = records.filter(function (record) {
    return record.id !== id;
  });
  const confirmBtn = confirmMask.querySelector('[data-action="confirm-delete"]');
  if (confirmBtn) {
    confirmBtn.disabled = true;
  }
  try {
    await persist(nextRecords);
    records = nextRecords;
    showError('');
    closeConfirm();
    renderAll();
  } catch (err) {
    closeConfirm();
    showError('删除失败，请重试。');
  } finally {
    if (confirmBtn) {
      confirmBtn.disabled = false;
    }
  }
}

function setFilter(next) {
  filter = next === ALL || STAGES.indexOf(next) >= 0 ? next : ALL;
  renderAll();
}

shell.addEventListener('click', function (event) {
  const target = event.target;
  if (!(target instanceof Element)) {
    return;
  }

  const actionEl = target.closest('[data-action]');
  if (actionEl) {
    const action = actionEl.getAttribute('data-action');
    if (action === 'open-create') {
      openForm(null);
      return;
    }
    if (action === 'cancel-form') {
      closeForm();
      return;
    }
    if (action === 'edit') {
      const id = actionEl.getAttribute('data-id');
      const record = records.find(function (item) { return item.id === id; });
      if (record) {
        openForm(record);
      }
      return;
    }
    if (action === 'delete') {
      openConfirm(actionEl.getAttribute('data-id'));
      return;
    }
    if (action === 'cancel-delete') {
      closeConfirm();
      return;
    }
    if (action === 'confirm-delete') {
      handleDelete();
      return;
    }
  }

  const filterEl = target.closest('[data-filter]');
  if (filterEl) {
    setFilter(filterEl.getAttribute('data-filter'));
  }
});

formEl.addEventListener('submit', handleSubmit);

document.addEventListener('keydown', function (event) {
  if (event.key !== 'Escape') {
    return;
  }
  if (!confirmMask.hidden) {
    closeConfirm();
    return;
  }
  if (!formMask.hidden) {
    closeForm();
  }
});

async function init() {
  let state = null;
  try {
    state = await appStore.getState();
  } catch (err) {
    state = null;
  }

  const stored = state && Object.prototype.hasOwnProperty.call(state, STORAGE_KEY) ? state[STORAGE_KEY] : undefined;

  if (Array.isArray(stored)) {
    records = stored.map(normalizeRecord);
  } else {
    records = [];
    try {
      await persist(records);
    } catch (err) {
      showError('初始化数据失败，当前更改可能无法保存。');
    }
  }

  renderAll();
}

await init();

