:root {
  --blue-900: #0b2545;
  --blue-700: #14508c;
  --blue-600: #1a6fd4;
  --blue-500: #2b86e8;
  --blue-100: #e3eefb;
  --blue-050: #f2f7fe;
  --line: #d3e2f4;
  --text: #10233d;
  --text-soft: #5b7391;
  --white: #ffffff;
  --danger: #c62828;
  --danger-soft: #fdecec;
  --radius: 14px;
  --shadow: 0 6px 18px rgba(16, 60, 120, 0.10);
}

#app {
  min-height: 100vh;
  background: linear-gradient(180deg, var(--blue-050) 0%, #e8f1fc 55%, #dfeaf9 100%);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", "Helvetica Neue", Arial, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 18px 14px 48px;
}

.app-header {
  background: linear-gradient(135deg, var(--blue-700), var(--blue-500));
  color: var(--white);
  border-radius: var(--radius);
  padding: 16px 16px 18px;
  box-shadow: var(--shadow);
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.app-title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.app-sub {
  margin: 8px 0 0;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.85);
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 16px;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  min-height: 42px;
}

.btn-primary {
  background: var(--white);
  color: var(--blue-700);
  font-weight: 600;
  border-color: var(--white);
}

.btn-primary:hover {
  background: var(--blue-100);
}

.btn-ghost {
  background: var(--white);
  color: var(--blue-700);
  border-color: var(--line);
}

.btn-ghost:hover {
  background: var(--blue-050);
}

.btn-danger {
  background: var(--danger);
  color: var(--white);
  border-color: var(--danger);
  font-weight: 600;
}

.btn-danger:hover {
  background: #a91f1f;
}

.stats {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  margin-top: 14px;
}

.stat-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 10px 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  cursor: pointer;
  font-family: inherit;
  color: var(--text);
  box-shadow: 0 2px 8px rgba(16, 60, 120, 0.06);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.stat-card:hover {
  border-color: var(--blue-500);
}

.stat-card.is-active {
  background: var(--blue-100);
  border-color: var(--blue-600);
}

.stat-label {
  font-size: 12px;
  color: var(--text-soft);
  white-space: nowrap;
}

.stat-value {
  font-size: 19px;
  font-weight: 700;
  color: var(--blue-700);
}

.toolbar {
  margin-top: 16px;
}

.filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  border: 1px solid var(--line);
  background: var(--white);
  color: var(--blue-700);
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  min-height: 38px;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.chip:hover {
  border-color: var(--blue-500);
}

.chip.is-active {
  background: var(--blue-600);
  border-color: var(--blue-600);
  color: var(--white);
  font-weight: 600;
}

.list-summary {
  margin: 12px 2px 0;
  font-size: 13px;
  color: var(--text-soft);
}

.error-banner {
  margin: 12px 0 0;
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--danger-soft);
  color: var(--danger);
  border: 1px solid #f3c9c9;
  font-size: 13px;
}

.list-section {
  margin-top: 12px;
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-left: 4px solid var(--blue-500);
  border-radius: var(--radius);
  padding: 12px 14px;
  box-shadow: 0 2px 10px rgba(16, 60, 120, 0.06);
}

.record-card[data-stage="待投递"] {
  border-left-color: #7f9dc0;
}

.record-card[data-stage="已投递"] {
  border-left-color: var(--blue-600);
}

.record-card[data-stage="面试中"] {
  border-left-color: #0f9d8f;
}

.record-card[data-stage="已结束"] {
  border-left-color: #8a94a6;
}

.record-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--blue-900);
  word-break: break-word;
}

.record-position {
  margin: 3px 0 0;
  font-size: 13px;
  color: var(--text-soft);
  word-break: break-word;
}

.stage-tag {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--blue-100);
  color: var(--blue-700);
  white-space: nowrap;
}

.stage-tag[data-stage="面试中"] {
  background: #e0f5f2;
  color: #0b6f65;
}

.stage-tag[data-stage="已结束"] {
  background: #eceff3;
  color: #5a6472;
}

.record-meta {
  margin: 10px 0 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  font-size: 13px;
  color: var(--text-soft);
}

.record-meta span {
  word-break: break-word;
}

.record-note {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--text);
  background: var(--blue-050);
  border-radius: 8px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  margin-top: 12px;
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.record-actions .btn {
  padding: 8px 14px;
  min-height: 38px;
  font-size: 13px;
}

.btn-edit {
  background: var(--blue-050);
  color: var(--blue-700);
  border-color: var(--line);
}

.btn-edit:hover {
  background: var(--blue-100);
}

.btn-delete {
  background: var(--white);
  color: var(--danger);
  border-color: #f0c4c4;
}

.btn-delete:hover {
  background: var(--danger-soft);
}

.empty-hint {
  margin: 26px 0 0;
  text-align: center;
  color: var(--text-soft);
  font-size: 14px;
}

.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(11, 37, 69, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 50;
}

.modal-mask[hidden] {
  display: none;
}

.modal {
  width: 100%;
  max-width: 460px;
  max-height: 88vh;
  overflow-y: auto;
  background: var(--white);
  border-radius: 16px;
  padding: 18px 16px 16px;
  box-shadow: 0 18px 40px rgba(11, 37, 69, 0.28);
}

.modal-title {
  margin: 0 0 14px;
  font-size: 17px;
  color: var(--blue-900);
}

.record-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--blue-700);
}

.field input,
.field select,
.field textarea {
  width: 100%;
  font-family: inherit;
  font-size: 15px;
  color: var(--text);
  background: var(--blue-050);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 10px 12px;
  min-height: 44px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field textarea {
  resize: vertical;
  min-height: 76px;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--blue-600);
  box-shadow: 0 0 0 3px rgba(43, 134, 232, 0.18);
  background: var(--white);
}

.field input::placeholder,
.field textarea::placeholder {
  color: #93a8c2;
}

.form-error {
  margin: 0;
  padding: 8px 10px;
  border-radius: 8px;
  background: var(--danger-soft);
  color: var(--danger);
  font-size: 13px;
  border: 1px solid #f3c9c9;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 4px;
}

.modal-confirm .confirm-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--text-soft);
  word-break: break-word;
}

@media (max-width: 420px) {
  .app-shell {
    padding: 14px 10px 40px;
  }

  .stats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .app-title {
    font-size: 18px;
  }

  .header-top .btn {
    padding: 9px 12px;
  }
}
